package br.com.admeclesial.application.financeiro; import org.springframework.beans.factory.annotation.Autowired; import br.com.admeclesial.application.usuario.SegurancaOrganizacaoService; import br.com.admeclesial.domain.financeiro.*; import br.com.admeclesial.infrastructure.persistence.financeiro.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.*; @Service public class MovimentacaoFinanceiraApplicationService { @Autowired SegurancaOrganizacaoService seguranca; final MovimentacaoFinanceiraRepository repo; final ContaFinanceiraRepository contas; final br.com.admeclesial.infrastructure.persistence.financeiro.CategoriaFinanceiraRepository categorias; final br.com.admeclesial.infrastructure.persistence.financeiro.CentroCustoRepository centros; public MovimentacaoFinanceiraApplicationService(MovimentacaoFinanceiraRepository r,ContaFinanceiraRepository c,br.com.admeclesial.infrastructure.persistence.financeiro.CategoriaFinanceiraRepository ca,br.com.admeclesial.infrastructure.persistence.financeiro.CentroCustoRepository ce){repo=r;contas=c;categorias=ca;centros=ce;} @Transactional public MovimentacaoFinanceira salvar(MovimentacaoFinanceiraRequest r){var c=contas.findByUuid(r.contaFinanceiraUuid()).orElseThrow(()->new IllegalArgumentException("Conta financeira não encontrada.")); if(seguranca!=null)seguranca.validarAcessoId(c.getOrganizacaoEclesialId()); if(!c.getAtivo())throw new IllegalArgumentException("Conta financeira inativa."); if(r.valor().signum()<=0)throw new IllegalArgumentException("Valor deve ser positivo."); if(r.tipo()==TipoMovimentacaoFinanceira.TRANSFERENCIA)throw new IllegalArgumentException("Transferência deve ser registrada pelo fluxo de transferência financeira."); var e=new MovimentacaoFinanceira();e.setContaFinanceiraId(c.getId());e.setCategoriaFinanceiraId(r.categoriaFinanceiraUuid()==null?null:categorias.findByUuid(r.categoriaFinanceiraUuid()).orElseThrow(()->new IllegalArgumentException("Categoria financeira não encontrada.")).getId()); if(r.centroCustoUuid()!=null){var cc=centros.findByUuid(r.centroCustoUuid()).orElseThrow(()->new IllegalArgumentException("Centro de custo não encontrado.")); if(!cc.getAtivo())throw new IllegalArgumentException("Centro de custo inativo."); if(!cc.getOrganizacaoEclesialId().equals(c.getOrganizacaoEclesialId()))throw new IllegalArgumentException("O centro de custo deve pertencer à organização da conta financeira."); e.setCentroCustoId(cc.getId());}e.setTipo(r.tipo());e.setValor(r.valor());e.setDataMovimentacao(r.dataMovimentacao());e.setCompetencia(r.competencia());e.setDescricao(r.descricao());e.setStatus(r.status()==null?StatusMovimentacaoFinanceira.CONFIRMADA:r.status());return repo.save(e);} @Transactional(readOnly=true) public List<MovimentacaoFinanceira> listar(){return repo.findAllByOrderByDataMovimentacaoDesc().stream().filter(e -> {var c=contas.findById(e.getContaFinanceiraId()).orElse(null);if(c==null)return false;try{if(seguranca!=null)seguranca.validarAcessoId(c.getOrganizacaoEclesialId());return true;}catch(org.springframework.security.access.AccessDeniedException ex){return false;}}).toList();}}